const float exposure = 1.0;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = highpTexelFetch(iChannel0, ivec2(fragCoord), 0);
    vec2 lastPS = i_pathSample32(fragColor.a);
    fragColor.rgb = exposure * fragColor.rgb / lastPS.y;
    fragColor.rgb = linear_srgb(ACESFitted(fragColor.rgb));
}

// math constants
const highp float
    SQRT2 = 1.4142136, SC45 = 0.7071068, D2R = 0.0174533,
    eps = 0.001, ieps = 0.999, epsCol = 0.0039062,
    QTRPI = 0.7853981, HPI = 1.5707963, PI = 3.1415926, TWOPI = 6.2831853,
    iQTRPI = 1.2732396, iHPI = 0.6366197, iPI = 0.3183098, iTWOPI = 0.1591549;
const highp float PHI1 = 1.0 - 1.0 / float(1.61803398);
const highp vec2  PHI2 = 1.0 - 1.0 / pow(vec2(1.32471795), vec2(1.0, 2.0));
const highp vec3  PHI3 = 1.0 - 1.0 / pow(vec3(1.22074408), vec3(1.0, 2.0, 3.0));

// camera properties
const float	znear = 0.03125, zfar = 128.0, FOV = 80.0;
const int MAX_RAY_BOUNCES = 2;
const int MAX_RAY_STEPS = 128;
const int MAX_SHADOW_STEPS = 64;
const int TEMPORAL_SMOOTHING = 32;
const int BIAS_WEIGHT = 32;

// generate a z order curve for each pixel/frame
int genSeed(in int f, in ivec2 c) {
    return (c.x + c.y*2 + f) + (c.x*1155 ^ c.y*2244) & 0xFFFF;
}

// r2 low discrepancy sequence
float r21(in int v) {
    return fract(PHI1 * float(v));
}

vec2 r22(in int v) {
    return fract(PHI2 * float(v));
}

vec3 r23(in int v) {
    return fract(PHI3 * float(v));
}

mat3 basis(in vec3 n) {
    float s = (n.z >= 0.0)? 1.0: -1.0;
    float a = 1.0 / (s + n.z);
    float b = -n.x*n.y*a;
    return mat3(-vec3(b, s - n.y*n.y*a, -n.y), vec3(1.0 - n.x*n.x*a*s, b*s, -n.x*s), n);
}

// orthonormal basis assuming up is +y
mat3 basisUp(in vec3 forward) {
    vec3 down = vec3(0.0, -1.0, 0.0);
    vec3 right = normalize(cross(forward, down));
    return mat3(right, normalize(cross(forward, right)), forward);
}

// fast orthogonal matrix inverse
mat4 orthoInverse(in mat4 m) {
    mat3 r = transpose(mat3(m));
    return mat4(
        vec4(r[0], 0.0),
        vec4(r[1], 0.0),
        vec4(r[2], 0.0),
        vec4(r * -m[3].xyz, 1.0)
    );
}

// construct 4x4 view mat from camera origin, forward direction
mat4 viewMat(in vec3 origin, in vec3 direction) {
    mat3 bas = basisUp(direction);
    return mat4(
        vec4(bas[0], 0.0),
        vec4(bas[1], 0.0),
        vec4(bas[2], 0.0),
        vec4(origin, 1.0)
    );
}

// construct 4x4 projection mat using offaxis parameters, aspect ratio, FOV
mat4 projectionMat(in vec2 offaxis, in float aspect, in float fov) {
    // proj parameters
    float f = zfar;
    float n = znear;
    float fovrad = fov * D2R;
    float r =  n * aspect * tan(0.5 * (fovrad - offaxis.x));
    float l = -n * aspect * tan(0.5 * (fovrad + offaxis.x));
    float t =  n          * tan(0.5 * (fovrad - offaxis.y));
    float b = -n          * tan(0.5 * (fovrad + offaxis.y));
    // construct proj mat
    return mat4(
        2.0*n/(r-l),         0.0, (r+l)/(r-l),           0.0,
                0.0, 2.0*n/(t-b), (t+b)/(t-b),           0.0,
                0.0,         0.0, (f+n)/(f-n), 2.0*f*n/(f-n),
                0.0,         0.0,         1.0,           0.0
    );
}

// project the pixel at ndc into a worldspace ray
void getCameraRay(in mat4 view, in mat4 proj, in vec2 ndc, out vec3 ro, out vec3 rd) {
    ro = view[3].xyz;
    vec4 ndch = transpose(inverse(proj)) * vec4(ndc, 1.0, 1.0);
    rd = normalize(mat3(view) * vec3(ndch.xy, 1.0));
}

// project a worldspace location hl into camera NDC using its view projection
vec3 reprojCoordsNDC(in mat4 view, in mat4 proj, in vec3 hl) {
    vec4 camspace = orthoInverse(view) * vec4(hl, 1.0);
    vec4 ndch = camspace * proj;
    return vec3(ndch.xy / ndch.w, length(camspace));
}

// Thanks mla - https://www.shadertoy.com/view/4cGGWw
vec4 highpTexelFetch(highp sampler2D chan, ivec2 px, int lod) {
    return texelFetch(chan, px, lod);
}

// Thanks iq - https://www.shadertoy.com/view/llfcRl
vec2 spheremap64(in vec3 nor) {
    return nor.xy * inversesqrt(2.0*nor.z+2.0);
}
vec3 i_spheremap64(in vec2 v) {
    float f = dot(v,v);
    return vec3( 2.0*v*sqrt(1.0-f), 1.0-2.0*f );
}

// store a path length float and a sample number integer in a single float
float pathSample32(in vec2 ls) {
    int l = int(float(0xFFFF) * min(1.0, ls.x / zfar));
    int s = int(min(float(0x00FF), ls.y));
    return float((s << 16) | l);
}
vec2 i_pathSample32(in float ps) {
    int l = int(ps) & 0xFFFF;
    int s = (int(ps) >> 16) & 0x00FF;
    return vec2(float(l) / float(0xFFFF) * zfar, float(s));
}

// 3D reproject given image, distance, pixel location (see reprojCoordsNDC)
vec4 reprojectBuffer(in sampler2D iChannel, in ivec2 iChanRes, in float dist, in vec2 fc) {
    ivec2 ifc = ivec2(fc);
    vec2 w = fc - floor(fc);
    // bound check
    if (any( lessThan( ifc, ivec2(0) )) || any( greaterThan( ifc, iChanRes-1)))
        return vec4(0.0, 0.0, 0.0, pathSample32(vec2(dist, BIAS_WEIGHT)));
    // get the 4 neighboring pixel values
    vec4 b   = highpTexelFetch(iChannel, ifc,               0);
    vec4 bx  = highpTexelFetch(iChannel, ifc + ivec2(1, 0), 0);
    vec4 by  = highpTexelFetch(iChannel, ifc + ivec2(0, 1), 0);
    vec4 bxy = highpTexelFetch(iChannel, ifc + ivec2(1, 1), 0);
    // extract path length, number of samples per pixel
    vec2 a   = i_pathSample32(b.a  );
    vec2 ax  = i_pathSample32(bx.a );
    vec2 ay  = i_pathSample32(by.a );
    vec2 axy = i_pathSample32(bxy.a);
    // path length filter
    float d   = float(abs(a.x   - dist) < 0.3);
    float dx  = float(abs(ax.x  - dist) < 0.3);
    float dy  = float(abs(ay.x  - dist) < 0.3);
    float dxy = float(abs(axy.x - dist) < 0.3);
    float ttl = d + dx + dy + dxy;
    // got or nothing
    if (int(ttl) < 1)
        return vec4(0.0, 0.0, 0.0, pathSample32(vec2(dist, BIAS_WEIGHT)));
    // bilinear (most pixels)
    if (int(ttl) == 4) {
        // norm sample number?
        b.rgb /= a.y;
        bx.rgb /= ax.y;
        by.rgb /= ay.y;
        bxy.rgb /= axy.y;
        float mina = min(min(a.y, ax.y), min(ay.y, axy.y));
        float maxa = max(max(a.y, ax.y), max(ay.y, axy.y));
        // inerpolate rgb normalized by number of samples
        vec3 bilinrgb = mix(mix(b.rgb, bx.rgb, w.x), mix(by.rgb, bxy.rgb, w.x), w.y);
        // num samples should be an integer
        return vec4(max(vec3(eps), bilinrgb * maxa), pathSample32(vec2(dist, maxa)));
    }
    // edge condition, literally
    float maxa = max(max(a.y*d, ax.y*dx), max(ay.y*dy, axy.y*dxy));
    vec3 rgb = (b.rgb*d + bx.rgb*dx + by.rgb*dy + bxy.rgb*dxy) / ttl;
    return vec4(max(vec3(eps), rgb), pathSample32(vec2(dist, maxa)));
}

// thanks iradicator
float dfSmooth1(in vec2 fc, in float v) { 
    vec2 q = vec2(uvec2(fc.xy) & uvec2(1));
    q = q * 2.0 - 1.0;    
    v -= 0.5 * dFdx(v) * q.x;
    v -= 0.5 * dFdy(v) * q.y;
    return v;
}
vec3 dfSmooth3(in vec2 fc, in vec3 v) { 
    vec2 q = vec2(uvec2(fc.xy) & uvec2(1));
    q = q * 2.0 - 1.0;    
    v -= 0.5 * dFdx(v) * q.x;
    v -= 0.5 * dFdy(v) * q.y;
    return v;
}

// Thanks Paniq
vec3 linear_srgb(in vec3 x) {
    return mix(1.055*pow(x, vec3(1./2.4)) - 0.055, 12.92*x, step(x, vec3(0.0031308)));
}

vec3 srgb_linear(in vec3 x) {
    return mix(pow((x + 0.055)/1.055,vec3(2.4)), x / 12.92, step(x, vec3(0.04045)));
}

// Paniq's ACES fitted from https://github.com/TheRealMJP/BakingLab/blob/master/BakingLab/ACES.hlsl
vec3 ACESFitted(in vec3 color) {
    // ODT_SAT => XYZ => D60_2_D65 => sRGB
    color = color * mat3(
        0.59719, 0.35458, 0.04823,
        0.07600, 0.90834, 0.01566,
        0.02840, 0.13383, 0.83777
    );
    // Apply RRT and ODT
    vec3 a = color * (color + 0.0245786) - 0.000090537;
    vec3 b = color * (0.983729 * color + 0.4329510) + 0.238081;
    color = a / b;
    // Back to color space
    color = color * mat3(
         1.60475, -0.53108, -0.07367,
        -0.10208,  1.10813, -0.00605,
        -0.00327, -0.07276,  1.07602
    );
    // Clamp to [0, 1]
    return clamp(color, 0.0, 1.0);
}

// thanks XT95 https://www.shadertoy.com/view/Dtl3WS
float F_Schlick(float f0, float f90, float theta) {
    return f0 + (f90 - f0) * pow(1.0 - theta, 5.0);
}

// thanks Jonathan Dupuy - https://arxiv.org/pdf/2306.05044
// Sampling the visible hemisphere as half vectors
vec3 SampleVndf_Hemisphere(vec2 U, vec3 wi) {
    // sample a spherical cap in (-wi.z, 1]
    float phi = 2.0 * PI * U.x;
    float z = (1.0 - U.y) * (1.0 + wi.z) - wi.z;
    float sinTheta = sqrt(clamp(1.0 - z * z, 0.0, 1.0));
    float x = sinTheta * cos(phi);
    float y = sinTheta * sin(phi);
    vec3 c = vec3(x, y, z);
    // compute halfway direction
    vec3 h = c + wi;
    // return without normalization (as this is done later)
    return h;
}

// Sampling Visible GGX Normals with Spherical Caps
vec3 SampleVndf_GGX(vec2 U, vec3 wi, vec2 alpha) {
    // warp to the hemisphere configuration
    vec3 wiStd = normalize(vec3(wi.xy * alpha, wi.z));
    // sample the hemisphere (see implementation 2 or 3)
    vec3 wmStd = SampleVndf_Hemisphere(U, wiStd);
    // warp back to the ellipsoid configuration
    vec3 wm = normalize(vec3(wmStd.xy * alpha, wmStd.z));
    // return final normal
    return wm;
}

// thanks Stephen Hill - https://blog.selfshadow.com/sandbox/multi_compare_1.html
// Adapted from "Multiple-Scattering Microfacet BSDFs with the Smith Model" - https://eheitzresearch.wordpress.com/240-2/
vec3 SampleGGXPhaseFunction(in vec2 U, in vec3 wi, in vec2 alpha, in float f0, out float pdf) {
    // Generate micro normal according to the distribution of visible normals
    vec3 h = SampleVndf_GGX(U, wi, alpha);
    // [0, 1] range
    float vdoth = clamp(dot(wi, h), 0.0, 1.0);
    // Schlick Fresnel factor
    pdf = F_Schlick(f0, 1.0, vdoth);
    // Perfect mirror reflection
    return 2.0*h*vdoth - wi;
}

// materials
const int mat_air = 0;
const int mat_sphere = 1;
const int mat_light = 2;

// lights
const vec4 light = vec4(0.0, 3.0, 0.5, 1.0);

// scene
vec2 sdMin(in vec2 a, in vec2 b) {
    return (a.x < b.x)? a: b;
}

vec2 sdf(in vec3 c) {
    vec2 d = vec2(zfar, mat_air);
    d = sdMin(d, vec2(distance(c, vec3(0.0)) - ieps, mat_sphere));
    d = sdMin(d, vec2(distance(c, light.xyz) - light.w, mat_light));
    d = sdMin(d, vec2(c.z - c.y * 0.1 + 0.5, mat_sphere));
    return d;
}

// Thanks Nimitz - https://www.shadertoy.com/view/Xts3WM
vec4 norcurv(in vec3 pt, in float ep) {
    vec2 e = vec2(-1.0, 1.0)*ep;
    float t1 = sdf(pt + e.yxx).x, t2 = sdf(pt + e.xxy).x;
    float t3 = sdf(pt + e.xyx).x, t4 = sdf(pt + e.yyy).x;
    return vec4(normalize(e.yxx*t1 + e.xxy*t2 + e.xyx*t3 + e.yyy*t4), (t1+t2+t3+t4 - 4.0*sdf(pt))/(ep*ep));
}

// relaxed raymarching
void raymarch(in vec3 rayPos, in vec3 rayDir, const int MAX_STEPS, out float t, out int mat) {
    mat = 0;
    t = eps;
    int lm = 0;
    float inside = sign(sdf(rayPos).x);
    float relax = 1.0;
    float lastT = t;
    for (int i = 0; i < MAX_STEPS; i++) {
        vec2 sd = sdf(rayPos + rayDir * t) * inside;
        if (sd.x < eps) {
            if (relax >= 1.0) {
                relax = 0.5;
                t = lastT;
            } else {
                mat = int(sd.y);
                return;
            }
        }
        lastT = t;
        t += sd.x * relax;
        lm = int(sd.y);
        if (t > zfar) {
            return;
        }
    }
    mat = lm;
}

// G buffer

void getCameraTransform(float time, out vec3 pos, out vec3 fwd) {
    time = sin(time * 0.01) * 0.1;
    pos = vec3(5.0 * sin(time), 1.0, 5.0 * cos(time));
    fwd = normalize(vec3(-pos.x, 0.0, -pos.z));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    // pixel shader coords
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 ndc = uv * 2.0 - 1.0;

    // current camera properties
    vec3 cur_pos, cur_fwd;
    getCameraTransform(float(iFrame), cur_pos, cur_fwd);

    if (fragCoord.y < 1.0) {
        if (fragCoord.x < 1.0) {
            fragColor = highpTexelFetch(iChannel0, ivec2(2, 0), 0);
            return;
        } else if (fragCoord.x < 2.0) {
            fragColor = highpTexelFetch(iChannel0, ivec2(3, 0), 0);
            return;
        } else if (fragCoord.x < 3.0) {
            fragColor = vec4(cur_pos, 1.0);
            return;
        } else if (fragCoord.x < 4.0) {
            fragColor = vec4(cur_fwd, 1.0);
            return;
        }
    }

    // camera view proj matrices
    mat4 view = viewMat(cur_pos, cur_fwd);
    mat4 proj = projectionMat(vec2(0.0), iResolution.x / iResolution.y, FOV);

    // get pixel ray to march
    vec3 ro, rd;
    getCameraRay(view, proj, ndc, ro, rd);

    // main scene raymarch
    int m;
    float t;
    raymarch(ro, rd, MAX_RAY_STEPS, t, m);
    vec4 nc = norcurv(ro + rd * t, eps);

    // encode into G buffer
    fragColor = vec4(t, m, spheremap64(nc.xyz));
}

// shading

#define USE_DF_SMOOTH

const vec3 lightCol = vec3(PI);

void textureMap(in int m, in vec3 h, in vec3 n, out vec3 diff, out vec3 spec, out vec3 emis, out vec2 rough) {
     diff = vec3(1.0);
     spec = vec3(1.0);
     emis = vec3(float(m == mat_light));
     rough = vec2(0.999);
}

vec3 pathtrace(in vec2 fragCoord, vec3 ro, vec3 rd, float t, vec3 n, int m) {

    // main hit sky
    if (t >= zfar) {
        return vec3(0.0);
    }

#ifdef USE_DF_SMOOTH
    bool shouldSmooth = abs(dfSmooth1(fragCoord, t) - t) < 0.1;
#endif

    vec3 col = vec3(0.0);
    vec3 rc = vec3(1.0);

    for (int i = 0; i < MAX_RAY_BOUNCES; i++) {

        vec3 h = ro + rd * t;
        // normal looking!
        //int seed = genSeed(iFrame + i, ivec2(fragCoord));
        // raining!
        int seed = genSeed(iFrame + i + int(h.y * 100.0), ivec2(h.xz * 100.0));

        // surface interaction with ray
        vec3 diffCol = vec3(0.0);
        vec3 specCol = vec3(0.0);
        vec3 emisCol = vec3(0.0);
        vec2 rough = vec2(0.0);
        textureMap(m, h, n, diffCol, specCol, emisCol, rough);

        // conservation of energy
        vec3 contrib = rc * emisCol;

#ifdef USE_DF_SMOOTH
        if (shouldSmooth)
            contrib = mix(contrib, dfSmooth3(fragCoord, contrib), 0.5);
#endif

        col += contrib;        

        // worldspace to GGX hemi (+z)
        mat3 rot = basis(n);
        vec3 view = transpose(rot) * -rd;

        // bounce ray
        float pdf;
        vec2 alpha = rough * rough;
        ro = h + n * eps;
        rd = rot * SampleGGXPhaseFunction(r22(seed), view, alpha, 1.75, pdf);
        rc *= diffCol * pdf;

        // raymarch scene
        t = zfar;
        m = mat_air;
        raymarch(ro, rd, MAX_SHADOW_STEPS, t, m);
        n = norcurv(ro + rd * t, eps).xyz;
    }

    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    // pixel shader coords
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 ndc = uv * 2.0 - 1.0;

    // get current camera properties
    vec3 cur_pos = highpTexelFetch(iChannel0, ivec2(2, 0), 0).xyz;
    vec3 cur_fwd = highpTexelFetch(iChannel0, ivec2(3, 0), 0).xyz;
    // current camera view proj matrices
    mat4 view = viewMat(cur_pos, cur_fwd);
    mat4 proj = projectionMat(vec2(0.0), iResolution.x / iResolution.y, FOV);
    // get pixel ray to march
    vec3 ro, rd;
    getCameraRay(view, proj, ndc, ro, rd);

    // get G buffer result
    vec4 g = highpTexelFetch(iChannel0, ivec2(fragCoord), 0);
    float t = g.r;
    int m = int(g.g);
    vec3 n = i_spheremap64(g.ba);

    // get last camera properties
    vec3 last_pos = highpTexelFetch(iChannel0, ivec2(0, 0), 0).xyz;
    vec3 last_fwd = highpTexelFetch(iChannel0, ivec2(1, 0), 0).xyz;
    // last view proj matrices
    mat4 lastView = viewMat(last_pos, last_fwd);
    mat4 lastProj = proj;
    // last frame reprojection in NDC
    vec3 lastNDC = reprojCoordsNDC(lastView, lastProj, ro + rd * t);
    vec2 lastPx = (lastNDC.xy * 0.5 + 0.5) * iChannelResolution[1].xy - 0.5;
    vec4 lastFrame = reprojectBuffer(iChannel1, ivec2(iChannelResolution[1].xy), lastNDC.z, lastPx);
    vec2 lastPS = i_pathSample32(lastFrame.a);

    // this is it
    vec3 col = pathtrace(fragCoord, ro, rd, t, n, m);

    // temporal smoothing
    if (lastPS.y > float(TEMPORAL_SMOOTHING)) {
        lastFrame.rgb *= float(TEMPORAL_SMOOTHING) / lastPS.y;
        lastPS.y = float(TEMPORAL_SMOOTHING);
    }

    // encode sample number in integer componenet
    fragColor = vec4(lastFrame.rgb + col, pathSample32(vec2(t, lastPS.y + 1.0)));

}
